        <>
            <Navbar/>
        <div>
        
            <div className="main">
                <h1 className="heading">
                    School Results
                </h1>
                <input className="input1" type="text" placeholder="enter the pin no">
                </input>
                   <input className="input1" type="text" placeholder="exam">
                </input>
         <button className="submit">Submit</button>
            </div>
            </div>
            </>
    );
}
export default ViewResult1;
